spec.expr:
max_over_time(
  cae_v16_test_duration_seconds{
    test_id=~"$test_id",
    vcs_repository_name=~"$repository", server_version=~"$server_version",
    vcs_repository_ref_name=~"$branch"
  }[1d]
)

max by (test_id, server_version) (
  quantile_over_time(0.5, cae_v16_test_duration_seconds{test_id=~"$test_id", vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent])
)

(
  time()
  -
  max by (test_id) (
    max_over_time(
      timestamp(cae_v16_test_duration_seconds{test_id=~"$test_id", vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"})[$baseline:5m]
    )
  )
) / 3600

max by (test_id, vcs_repository_name, server_version) (
  quantile_over_time(0.5, 
    cae_v16_test_duration_seconds{
      test_id=~"$test_id",
      vcs_repository_name=~"$repository",
      server_version=~"$server_version",
      vcs_repository_ref_name=~"$branch"
    }[$recent]
  )
)

max by (test_id, vcs_repository_name, server_version) (
  last_over_time(
    cae_v16_test_duration_seconds{
      test_id=~"$test_id",
      vcs_repository_name=~"$repository",
      server_version=~"$server_version",
      vcs_repository_ref_name=~"$branch"
    }[$recent]
  )
)

max by (test_id, vcs_repository_name, server_version) (
  quantile_over_time(0.5,
    cae_v16_test_duration_seconds{
      test_id=~"$test_id",
      vcs_repository_name=~"$repository",
      server_version=~"$server_version",
      vcs_repository_ref_name=~"$branch"
    }[$baseline] offset $recent
  )
)

max by (test_id, vcs_repository_name, server_version) (
  count_over_time(
    cae_v16_test_duration_seconds{
      test_id=~"$test_id",
      vcs_repository_name=~"$repository",
      server_version=~"$server_version",
      vcs_repository_ref_name=~"$branch"
    }[$baseline] offset $recent
  )
)

clamp_min(
  max by (test_id, vcs_repository_name, server_version) (
    quantile_over_time(0.5,
      cae_v16_test_duration_seconds{
      test_id=~"$test_id",
        vcs_repository_name=~"$repository",
        vcs_repository_ref_name=~"$branch"
      }[$baseline] offset $recent
    )
  ),
  0.05
)

max by (vcs_repository_name, test_result_status) (
  max_over_time(cae_v16_test_run_tests{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch", test_result_status=~"failed|error"}[1d])
)
